package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int    `json:"id"`
	Title   string `json:"title"`
	Completed bool  `json:"completed"`
}

// TodosRepository is an interface for interacting with a Todo database.
type TodosRepository interface {
	List(filter *TodoFilter) ([]Todo, error)
	Get(id int) (*Todo, error)
	Create(*Todo) (int, error)
	Update(int, *Todo) error
	Delete(id int) error
}

// NewTodosRepository returns a new TodosRepository using the given database connection.
func NewTodosRepository(db *sql.DB) TodosRepository {
	return &todosRepository{db}
}

type todosRepository struct {
	db *sql.DB
}

func (r todosRepository) List(filter *TodoFilter) ([]Todo, error) {
	var todos []Todo
	query := fmt.Sprintf("SELECT id, title, completed FROM todos WHERE %s", filter.ToSQL())
	rows, err := r.db.Query(query)
	if err != nil {
		return nil, fmt.Errorf("failed to list todos: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed); err != nil {
			return nil, fmt.Errorf("failed to scan todo: %w", err)
		}
		todos = append(todos, todo)
	}

	if rows.Err() != nil {
		return nil, fmt.Errorf("failed to scan rows: %w", rows.Err())
	}

	return todos, nil
}

func (r todosRepository) Get(id int) (*Todo, error) {
	var todo Todo
	query := fmt.Sprintf("SELECT id, title, completed FROM todos WHERE id = %d", id)
	if err := r.db.QueryRow(query).Scan(&todo.ID, &todo.Title, &todo.Completed); err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("todo not found: %w", err)
		}
		return nil, fmt.Errorf("failed to get todo: %w", err)
	}
	return &todo, nil
}

func (r todosRepository) Create(todo *Todo) (int, error) {
	result, err := r.db.Exec("INSERT INTO todos (title, completed) VALUES ($1, $2) RETURNING id", todo.Title, todo.Completed)
	if err != nil {
		return 0, fmt.Errorf("failed to create todo: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("failed to get last insert ID: %w", err)
	}
	return int(id), nil
}

func (r todosRepository) Update(id int, todo *Todo) error {
	result, err := r.db.Exec("UPDATE todos SET title = $1, completed = $2 WHERE id = $3", todo.Title, todo.Completed, id)
	if err != nil {
		return fmt.Errorf("failed to update todo: %w", err)
	}
	if result.RowsAffected() == 0 {
		return fmt.Errorf("todo not found: %w", err)
	}
	return nil
}

func (r todosRepository) Delete(id int) error {
	result, err := r.db.Exec("DELETE FROM todos WHERE id = $1", id)
	if err != nil {
		return fmt.Errorf("failed to delete todo: %w", err)
	}
	if result.RowsAffected() == 0 {
		return fmt.Errorf("todo not found: %w", err)
	}
	return nil
}

