package db

import (
	"database/sql"
	"todos/models"
)

func ListTodos(db *sql.DB) ([]models.Todo, error) {
	rows, err := db.Query("SELECT id, title, completed FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []models.Todo
	for rows.Next() {
		var todo models.Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed); err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

func GetTodoByID(db *sql.DB, id int) (*models.Todo, error) {
	var todo models.Todo
	err := db.QueryRow("SELECT id, title, completed FROM todos WHERE id = ?", id).Scan(&todo.ID, &todo.Title, &todo.Completed)
	if err != nil {
		return nil, err
	}

	return &todo, nil
}

func CreateTodo(db *sql.DB, title string) error {
	_, err := db.Exec("INSERT INTO todos (title, completed) VALUES ($1, $2)", title, false)
	return err
}

func UpdateTodo(db *sql.DB, id int, title string) error {
	_, err := db.Exec("UPDATE todos SET title = $1 WHERE id = ?", title, id)
	return err
}

func DeleteTodo(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM todos WHERE id = ?", id)
	return err
}

