	Title       string    `db:"title" validate:"required"`
	Completed   bool      `db:"completed"`
	CreatedAt   time.Time `db:"created_at"`
	UpdatedAt   time.Time `db:"updated_at"`
}

func (t *Todo) Create(db *sql.DB) error {
	query := `INSERT INTO todos (title, completed) VALUES ($1, $2) RETURNING id;`
	return db.QueryRow(query, t.Title, t.Completed).Scan(&t.ID)
}

func (t *Todo) Get(db *sql.DB, id int) error {
	query := `SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1;`
	return db.QueryRow(query, id).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
}

func (t *Todo) Update(db *sql.DB, id int) error {
	query := `UPDATE todos SET title = $2, completed = $3, updated_at = $4 WHERE id = $5;`
	_, err := db.Exec(query, t.Title, t.Completed, time.Now(), id)
	return err
}

func (t *Todo) Delete(db *sql.DB, id int) error {
	_, err := db.Exec(`DELETE FROM todos WHERE id = $1;`, id)
	return err
}

func (t *Todo) List(db *sql.DB) ([]*Todo, error) {
	var todos []*Todo
	rows, err := db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos;`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, &todo)
	}
	return todos, nil
}

