package db

import (
	"database/sql"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

func (t *Todo) Create(db *sql.DB, title string) error {
	return db.QueryRow(`
		INSERT INTO todos (title, completed)
		VALUES ($1, $2)
		RETURNING id
	`, title, false).Scan(&t.ID)
}

func (t *Todo) Update(db *sql.DB, title string, completed bool) error {
	return db.Exec(`
		UPDATE todos
		SET title = $1, completed = $2
		WHERE id = $3
	`, title, completed, t.ID)
}

func (t *Todo) Delete(db *sql.DB) error {
	_, err := db.Exec("DELETE FROM todos WHERE id = $1", t.ID)
	return err
}

func GetTodo(db *sql.DB, id int) (*Todo, error) {
	t := &Todo{}
	err := db.QueryRow(`
		SELECT id, title, completed, created_at, updated_at
		FROM todos
		WHERE id = $1
	`, id).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
	return t, err
}

func ListTodos(db *sql.DB) ([]Todo, error) {
	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	todos := []Todo{}
	for rows.Next() {
		var t Todo
		if err := rows.Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, t)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

