package handlers

import (
	"database/sql"
	"net/http"

	"github.com/gin-gonic/gin"
)

func ListTodos(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		todos, err := db.GetAllTodos()
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Unable to list todos"})
			return
		}
		c.JSON(http.StatusOK, todos)
	}
}

func GetTodo(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		id := c.Param("id")
		todo := &db.Todo{
			ID: parseInt(id),
		}
		if err := todo.Get(db); err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Todo not found"})
			return
		}
		c.JSON(http.StatusOK, todo)
	}
}

func CreateTodo(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		var todo db.Todo
		if err := c.ShouldBindJSON(&todo); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid request body"})
			return
		}
		if err := todo.Create(db); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "Unable to create todo"})
			return
		}
		c.JSON(http.StatusCreated, todo)
	}
}

func UpdateTodo(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		id := c.Param("id")
		var updateTodo db.Todo
		updateTodo.ID = parseInt(id)
		if err := c.ShouldBindJSON(&updateTodo); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid request body"})
			return
		}
		if err := updateTodo.Update(db); err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Todo not found"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"message": "Todo updated"})
	}
}

func DeleteTodo(db *sql.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		id := c.Param("id")
		todo := &db.Todo{
			ID: parseInt(id),
		}
		if err := todo.Delete(db); err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Todo not found"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"message": "Todo deleted"})
	}
}

func parseInt(s string) int {
	id, _ := strconv.Atoi(s)
	return id
}

