)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func GetTodos(c *gin.Context) {
	todos, err := db.ListTodos(db.GetDB())
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	var todoList []Todo
	for _, t := range todos {
		todoList = append(todoList, Todo{ID: t.ID, Title: t.Title, Completed: t.Completed, CreatedAt: t.CreatedAt, UpdatedAt: t.UpdatedAt})
	}

	c.JSON(http.StatusOK, todoList)
}

func GetTodo(c *gin.Context) {
	id, err := strconv.Atoi(c.Param("id"))
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid id"})
		return
	}

	todo := &db.Todo{}
	if err = todo.Get(db.GetDB(), id); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "Todo not found"})
		return
	}

	c.JSON(http.StatusOK, Todo{ID: todo.ID, Title: todo.Title, Completed: todo.Completed, CreatedAt: todo.CreatedAt, UpdatedAt: todo.UpdatedAt})
}

func CreateTodo(c *gin.Context) {
	var request struct {
		Title string `json:"title" binding:"required"`
	}

	if err := c.ShouldBindJSON(&request); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid request"})
		return
	}

	todo := &db.Todo{Title: request.Title}
	if err := todo.Insert(db.GetDB(), request.Title); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	c.JSON(http.StatusCreated, Todo{ID: todo.ID, Title: request.Title, Completed: false})
}

func UpdateTodo(c *gin.Context) {
	id, err := strconv.Atoi(c.Param("id"))
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid id"})
		return
	}

	request := struct {
		Title     *string `json:"title"`
		Completed *bool   `json:"completed"`
	}{}

	if err := c.ShouldBindJSON(&request); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid request"})
		return
	}

	todo := &db.Todo{}
	if err = todo.Get(db.GetDB(), id); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "Todo not found"})
		return
	}

	if request.Title == nil && request.Completed == nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "No fields to update"})
		return
	}

	if request.Title != nil {
		todo.Title = *request.Title
	}
	if request.Completed != nil {
		todo.Completed = *request.Completed
	}

	if err := todo.Update(db.GetDB(), id, todo.Title, todo.Completed); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	c.JSON(http.StatusOK, Todo{ID: todo.ID, Title: todo.Title, Completed: todo.Completed, CreatedAt: todo.CreatedAt, UpdatedAt: todo.UpdatedAt})
}

func DeleteTodo(c *gin.Context) {
	id, err := strconv.Atoi(c.Param("id"))
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Invalid id"})
		return
	}

	todo := &db.Todo{}
	if err = todo.Get(db.GetDB(), id); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "Todo not found"})
		return
	}

	if err := todo.Delete(db.GetDB(), id); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	c.JSON(http.StatusNoContent, nil)
}

