package handlers

import (
    "encoding/json"
    "net/http"

    "github.com/golang-jwt/jwt/v4"
    "github.com/lib/pq"

    "yourapp/db"
)

type Todo struct {
    ID          int64     `json:"id"`
    Title       string    `json:"title" binding:"required"`
    Completed   bool      `json:"completed"`
}

type TodosHandler struct {
    db *db.DB
}

func NewTodosHandler(db *db.DB) *TodosHandler {
    return &TodosHandler{db: db}
}

func (h *TodosHandler) List(w http.ResponseWriter, r *http.Request) {
    todos, err := h.db.ListTodos()
    if err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }

    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(todos)
}

func (h *TodosHandler) Get(w http.ResponseWriter, r *http.Request) {
    id := pq.Array(r.URL.Query()["id"])
    if len(id) != 1 {
        http.Error(w, "Invalid id", http.StatusBadRequest)
        return
    }

    todo, err := h.db.GetTodo(id[0])
    if err != nil {
        if errors.Is(err, db.ErrTodoNotFound) {
            http.Error(w, "Todo not found", http.StatusNotFound)
        } else {
            http.Error(w, err.Error(), http.StatusInternalServerError)
        }
        return
    }

    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(todo)
}

func (h *TodosHandler) Create(w http.ResponseWriter, r *http.Request) {
    var todo Todo
    if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
        http.Error(w, "Invalid request body", http.StatusBadRequest)
        return
    }

    if todo.Title == "" {
        http.Error(w, "Title is required", http.StatusBadRequest)
        return
    }

    err := h.db.CreateTodo(todo)
    if err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }

    w.WriteHeader(http.StatusCreated)
}

func (h *TodosHandler) Update(w http.ResponseWriter, r *http.Request) {
    id := pq.Array(r.URL.Query()["id"])
    if len(id) != 1 {
        http.Error(w, "Invalid id", http.StatusBadRequest)
        return
    }

    var update Todo
    if err := json.NewDecoder(r.Body).Decode(&update); err != nil {
        http.Error(w, "Invalid request body", http.StatusBadRequest)
        return
    }

    if update.Title == "" && update.Completed == false {
        http.Error(w, "Nothing to update", http.StatusBadRequest)
        return
    }

    err := h.db.UpdateTodo(id[0], update)
    if err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }

    w.WriteHeader(http.StatusOK)
}

func (h *TodosHandler) Delete(w http.ResponseWriter, r *http.Request) {
    id := pq.Array(r.URL.Query()["id"])
    if len(id) != 1 {
        http.Error(w, "Invalid id", http.StatusBadRequest)
        return
    }

    err := h.db.DeleteTodo(id[0])
    if err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }

    w.WriteHeader(http.StatusOK)
}

