package db

import (
	"database/sql"
	"time"

	"github.com/go-sql-driver/mysql"
)

type Todo struct {
	ID          int       `json:"id"`
	Title       string    `json:"title"`
	Completed   bool      `json:"completed"`
	CreatedAt   time.Time `json:"created_at"`
	UpdatedAt   time.Time `json:"updated_at"`
}

var db *sql.DB

func Connect(user, password, addr, dbname string) (*sql.DB, error) {
	dsn := mysql.DSN{
		User:     user,
		Passwd:   password,
		Net:      "tcp",
	 Addr:     addr,
		DBName:   dbname,
		Loc:      time.UTC,
		TimeZone: "UTC",
	Charset:  []string{"utf8mb4"},
	}
	return sql.Open("mysql", dsn.String())
}

func GetTodos() ([]Todo, error) {
	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}
	return todos, nil
}

func GetTodo(id int) (Todo, error) {
	var todo Todo
	if err := db.QueryRow("SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?", id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
		return Todo{}, err
	}
	return todo, nil
}

func CreateTodo(title string) (int, error) {
	result, err := db.Exec("INSERT INTO todos (title, completed) VALUES (?, ?)", title, false)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return int(id), nil
}

func UpdateTodo(id int, title *string, completed *bool) error {
	setClauses := []string{}
	params := []interface{}{}

	if title != nil {
		setClauses = append(setClauses, "title=?")
		params = append(params, title)
	}

	if completed != nil {
		setClauses = append(setClauses, "completed=?")
		params = append(params, completed)
	}

	setClause := strings.Join(setClauses, ", ")
	if setClause == "" {
		return errors.New("no fields to update")
	}

	params = append(params, id)
	_, err := db.Exec(fmt.Sprintf("UPDATE todos SET %s WHERE id=?", setClause), params...)
	return err
}

func DeleteTodo(id int) error {
	_, err := db.Exec("DELETE FROM todos WHERE id=?", id)
	return err
}

