	CreatedAt   sql.NullTime `json:"created_at"`
	UpdatedAt   sql.NullTime `json:"updated_at"`
}

func (t *Todo) Create(db *sql.DB) error {
	_, err := db.Exec(`
		INSERT INTO todos (title, completed)
		VALUES ($1, $2)
	`, t.Title, t.Completed)
	return err
}

func (t *Todo) Update(db *sql.DB) error {
	_, err := db.Exec(`
		UPDATE todos
		SET title = $1, completed = $2
		WHERE id = $3
	`, t.Title, t.Completed, t.ID)
	return err
}

func (t *Todo) GetByID(db *sql.DB, id int) error {
	return db.QueryRow(`
		SELECT id, title, completed, created_at, updated_at
		FROM todos WHERE id = $1
	`, id).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
}

func (t *Todo) Delete(db *sql.DB) error {
	_, err := db.Exec("DELETE FROM todos WHERE id = $1", t.ID)
	return err
}

