package db

import (
	"database/sql"
	"log"

	_ "github.com/mattn/go-sqlite3"
)

var db *sql.DB

func InitDB() error {
	var err error
	db, err = sql.Open("sqlite3", "todos.db")
	if err != nil {
		return err
	}
	log.Println("Database initialized successfully.")
	return nil
}

func CreateTodo(title string, completed bool) (int64, error) {
	stmt, err := db.Prepare("INSERT INTO todos (title, completed) VALUES (?, ?)")
	if err != nil {
		return 0, err
	}
	defer stmt.Close()
	result, err := stmt.Exec(title, completed)
	if err != nil {
		return 0, err
	}
	return result.LastInsertId()
}

func GetTodo(id int64) (map[string]interface{}, error) {
	var title string
	var completed bool
	err := db.QueryRow("SELECT title, completed FROM todos WHERE id = ?", id).Scan(&title, &completed)
	if err != nil {
		return nil, err
	}
	return map[string]interface{}{
		"id":        id,
		"title":     title,
		"completed": completed,
	}, nil
}

func UpdateTodo(id int64, title string, completed bool) (int64, error) {
	stmt, err := db.Prepare("UPDATE todos SET title = ?, completed = ? WHERE id = ?")
	if err != nil {
		return 0, err
	}
	defer stmt.Close()
	result, err := stmt.Exec(title, completed, id)
	if err != nil {
		return 0, err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return 0, err
	}
	return rowsAffected, nil
}

func DeleteTodo(id int64) (int64, error) {
	stmt, err := db.Prepare("DELETE FROM todos WHERE id = ?")
	if err != nil {
		return 0, err
	}
	defer stmt.Close()
	result, err := stmt.Exec(id)
	if err != nil {
		return 0, err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return 0, err
	}
	return rowsAffected, nil
}

func GetAllTodos() ([]map[string]interface{}, error) {
	rows, err := db.Query("SELECT id, title, completed FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var todos []map[string]interface{}
	for rows.Next() {
		var id int64
		var title string
		var completed bool
		err := rows.Scan(&id, &title, &completed)
		if err != nil {
			return nil, err
		}
		todos = append(todos, map[string]interface{}{
			"id":        id,
			"title":     title,
			"completed": completed,
		})
	}
	return todos, nil
}

