package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID          int
	Title       string
	Completed   bool
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

func GetTodo(id int) (Todo, error) {
	db, err := sql.Open("postgres", "host=localhost user=youruser dbname=yourschema sslmode=disable")
	if err != nil {
		return Todo{}, err
	}
	defer db.Close()

	var todo Todo
	err = db.QueryRow("SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1", id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return Todo{}, fmt.Errorf("Failed to get todo: %w", err)
	}

	return todo, nil
}

func ListTodos() ([]Todo, error) {
	db, err := sql.Open("postgres", "host=localhost user=youruser dbname=yourschema sslmode=disable")
	if err != nil {
		return []Todo{}, err
	}
	defer db.Close()

	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return []Todo{}, fmt.Errorf("Failed to list todos: %w", err)
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return []Todo{}, fmt.Errorf("Failed to scan todo row: %w", err)
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return []Todo{}, fmt.Errorf("Error iterating over rows: %w", err)
	}

	return todos, nil
}

func CreateTodo(title string) (int, error) {
	db, err := sql.Open("postgres", "host=localhost user=youruser dbname=yourschema sslmode=disable")
	if err != nil {
		return 0, err
	}
	defer db.Close()

	result, err := db.Exec("INSERT INTO todos (title) VALUES ($1) RETURNING id", title)
	if err != nil {
		return 0, fmt.Errorf("Failed to create todo: %w", err)
	}

	id, err := result.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("Failed to get last insert id: %w", err)
	}

	return int(id), nil
}

func UpdateTodo(id int, title string) error {
	db, err := sql.Open("postgres", "host=localhost user=youruser dbname=yourschema sslmode=disable")
	if err != nil {
		return err
	}
	defer db.Close()

	var changes int
	switch title {
	case "":
		changes, err = db.Exec("UPDATE todos SET completed = NOT completed WHERE id = $1", id)
	default:
		title = title
	}
	if err != nil {
		return fmt.Errorf("Failed to update todo: %w", err)
	}

	if changes == 0 {
		return fmt.Errorf("Todo not found")
	}

	return nil
}

func DeleteTodo(id int) error {
	db, err := sql.Open("postgres", "host=localhost user=youruser dbname=yourschema sslmode=disable")
	if err != nil {
		return err
	}
	defer db.Close()

	result, err := db.Exec("DELETE FROM todos WHERE id = $1", id)
	if err != nil {
		return fmt.Errorf("Failed to delete todo: %w", err)
	}

	changes, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("Failed to get rows affected: %w", err)
	}

	if changes == 0 {
		return fmt.Errorf("Todo not found")
	}

	return nil
}

