package db

import (
	"context"
	"database/sql"
)

type Todo struct {
	ID          int
	Title       string
	Completed   bool
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

func (db *DB) GetTodo(ctx context.Context, id int) (*Todo, error) {
	var todo Todo
	err := db.queryRow(ctx, `SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1`, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func (db *DB) ListTodos(ctx context.Context) ([]Todo, error) {
	rows, err := db.query(ctx, `SELECT id, title, completed, created_at, updated_at FROM todos`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}
	return todos, nil
}

func (db *DB) CreateTodo(ctx context.Context, title string) (*Todo, error) {
	var todo Todo
	err := db.queryRow(ctx, `INSERT INTO todos (title) VALUES ($1) RETURNING id, title, completed, created_at, updated_at`, title).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func (db *DB) UpdateTodo(ctx context.Context, id int, title string, completed bool) (*Todo, error) {
	var todo Todo
	err := db.queryRow(ctx, `UPDATE todos SET title = $2, completed = $3 WHERE id = $1 RETURNING id, title, completed, created_at, updated_at`, id, title, completed).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func (db *DB) DeleteTodo(ctx context.Context, id int) error {
	_, err := db.exec(ctx, `DELETE FROM todos WHERE id = $1`, id)
	return err
}

