package db

import (
	"database/sql"
	"errors"
)

type Todo struct {
	ID        int       `db:"id"`
	Title     string    `db:"title" validate:"required"`
	Completed bool      `db:"completed"`
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

func GetTodoByID(db *sql.DB, id int) (*Todo, error) {
	var todo Todo
	err := db.Get(&todo, "SELECT id, title, completed FROM todos WHERE id = ?", id)
	if err != nil {
		return nil, errors.New("todo not found")
	}
	return &todo, nil
}

func CreateTodo(db *sql.DB, title string) (int, error) {
	result, err := db.Exec("INSERT INTO todos (title) VALUES (?)", title)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return int(id), nil
}

func UpdateTodo(db *sql.DB, id int, title string) error {
	_, err := db.Exec("UPDATE todos SET title = ? WHERE id = ?", title, id)
	return err
}

func DeleteTodo(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM todos WHERE id = ?", id)
	return err
}

func ListTodos(db *sql.DB) ([]Todo, error) {
	var todos []Todo
	err := db.Select(&todos, "SELECT id, title, completed FROM todos")
	return todos, err
}

