import (
	"database/sql"
	"testing"

	_ "github.com/mattn/go-sqlite3"
)

func TestTodoCRUD(t *testing.T) {
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	todo := &Todo{Title: "test", Completed: true}

	// Create
	if err := todo.Create(db); err != nil {
		t.Fatal(err)
	}

	// Get
	if err := todo.GetByID(db, todo.ID); err != nil {
		t.Fatal(err)
	}
	if todo.Title != "test" || !todo.Completed {
		t.Errorf("Expected title to be 'test' and completed to be true, got %s %t", todo.Title, todo.Completed)
	}

	// Update
	todo.Title = "updated"
	if err := todo.Update(db, todo.ID); err != nil {
		t.Fatal(err)
	}
	if err := todo.GetByID(db, todo.ID); err != nil {
		t.Fatal(err)
	}
	if todo.Title != "updated" && todo.Completed {
		t.Errorf("Expected title to be 'updated' and completed to be true, got %s %t", todo.Title, todo.Completed)
	}

	// Delete
	if err := todo.Delete(db, todo.ID); err != nil {
		t.Fatal(err)
	}
	if err := todo.GetByID(db, todo.ID); err != sql.ErrNoRows {
		t.Errorf("Expected error to be sql.ErrNoRows, got %v", err)
	}
}

