package db

import (
	"database/sql"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func InitDB(dbPath string) (*sql.DB, error) {
	db, err := sql.Open("sqlite3", dbPath)
	if err != nil {
		return nil, err
	}
	return db, nil
}

func CreateTodo(db *sql.DB, title string, completed bool) (int, error) {
	result, err := db.Exec(`
		INSERT INTO todos (title, completed, created_at, updated_at)
		VALUES (?, ?, datetime('now'), datetime('now'))
	`, title, completed)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return int(id), nil
}

func GetTodos(db *sql.DB) ([]Todo, error) {
	rows, err := db.Query(`
		SELECT id, title, completed, created_at, updated_at FROM todos
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	return todos, nil
}

func GetTodoByID(db *sql.DB, id int) (Todo, error) {
	var todo Todo
	if err := db.QueryRow(`
		SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?
	`, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
		return todo, err
	}
	return todo, nil
}

func UpdateTodo(db *sql.DB, id int, title string, completed bool) error {
	_, err := db.Exec(`
		UPDATE todos SET title = ?, completed = ?, updated_at = datetime('now')
		WHERE id = ?
	`, title, completed, id)
	if err != nil {
		return err
	}
	return nil
}

func DeleteTodo(db *sql.DB, id int) error {
	_, err := db.Exec(`DELETE FROM todos WHERE id = ?`, id)
	if err != nil {
		return err
	}
	return nil
}

