func TestGetTodos(t *testing.T) {
	db, cleanup := setupDB(t)
	defer cleanup()

	CreateTodo(db, "Test Todo 1", false)
	CreateTodo(db, "Test Todo 2", true)

	todos, err := GetTodos(db)
	if err != nil {
		t.Fatalf("Failed to get todos: %v", err)
	}

	if len(todos) != 2 {
		t.Errorf("Incorrect number of todos returned")
	}
}

func TestGetTodoByID(t *testing.T) {
	db, cleanup := setupDB(t)
	defer cleanup()

	id, _ := CreateTodo(db, "Test Todo", false)

	todo, err := GetTodoByID(db, id)
	if err != nil {
		t.Fatalf("Failed to get todo by ID: %v", err)
	}

	if todo.Title != "Test Todo" || todo.Completed != false {
		t.Errorf("Retrieved todo has incorrect title or completed status")
	}
}

func TestUpdateTodo(t *testing.T) {
	db, cleanup := setupDB(t)
	defer cleanup()

	id, _ := CreateTodo(db, "Test Todo", false)

	err := UpdateTodo(db, id, "Updated Todo", true)
	if err != nil {
		t.Fatalf("Failed to update todo: %v", err)
	}

	todo, err := GetTodoByID(db, id)
	if err != nil {
		t.Fatalf("Failed to get updated todo: %v", err)
	}

	if todo.Title != "Updated Todo" || todo.Completed != true {
		t.Errorf("Updated todo has incorrect title or completed status")
	}
}

func TestDeleteTodo(t *testing.T) {
	db, cleanup := setupDB(t)
	defer cleanup()

	id, _ := CreateTodo(db, "Test Todo", false)

	err := DeleteTodo(db, id)
	if err != nil {
		t.Fatalf("Failed to delete todo: %v", err)
	}

	_, err = GetTodoByID(db, id)
	if err == nil {
		t.Errorf("Deleted todo was still found")
	}
}

func setupDB(t *testing.T) (*sql.DB, func()) {
	dbPath := ":memory:"
	db, err := InitDB(dbPath)
	if err != nil {
		t.Fatalf("Failed to initialize in-memory database: %v", err)
	}

	createTableSQL := `
	CREATE TABLE todos (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		title TEXT NOT NULL,
		completed BOOLEAN NOT NULL DEFAULT FALSE,
		created_at DATETIME NOT NULL,
		updated_at DATETIME NOT NULL
	);
	`
	_, err = db.Exec(createTableSQL)
	if err != nil {
		t.Fatalf("Failed to create todos table: %v", err)
	}

	cleanup := func() {
		db.Close()
	}

	return db, cleanup
}

