package handlers

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"

	"github.com/go-chi/chi/v5"
	"todoapp/db"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func NewRouter(db *db.SQLDB) *chi.Mux {
	r := chi.NewRouter()

	r.Get("/todos", func(w http.ResponseWriter, r *http.Request) {
		todos, err := db.GetTodos()
		if err != nil {
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(todos)
	})

	r.Post("/todos", func(w http.ResponseWriter, r *http.Request) {
		var todo Todo
		err := json.NewDecoder(r.Body).Decode(&todo)
		if err != nil || todo.Title == "" {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		id, err := db.CreateTodo(todo.Title, todo.Completed)
		if err != nil {
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}
		todo.ID = id
		json.NewEncoder(w).Encode(todo)
	})

	r.Get("/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, err := strconv.Atoi(chi.URLParam(r, "id"))
		if err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		todo, err := db.GetTodoByID(id)
		if err != nil {
			http.Error(w, "Not Found", http.StatusNotFound)
			return
		}
		json.NewEncoder(w).Encode(todo)
	})

	r.Put("/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, err := strconv.Atoi(chi.URLParam(r, "id"))
		if err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		var todo Todo
		err = json.NewDecoder(r.Body).Decode(&todo)
		if err != nil || (todo.Title == "" && !todo.Completed) {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		err = db.UpdateTodo(id, todo.Title, todo.Completed)
		if err != nil {
			http.Error(w, "Not Found", http.StatusNotFound)
			return
		}
		w.WriteHeader(http.StatusOK)
	})

	r.Delete("/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, err := strconv.Atoi(chi.URLParam(r, "id"))
		if err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		err = db.DeleteTodo(id)
		if err != nil {
			http.Error(w, "Not Found", http.StatusNotFound)
			return
		}
		w.WriteHeader(http.StatusOK)
	})

	return r
}

