package db

import (
	"database/sql"
	"log"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

func ConnectToDB() (*sql.DB, error) {
	connStr := "user=postgres dbname=todos sslmode=disable"
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		return nil, err
	}
	err = db.Ping()
	if err != nil {
		return nil, err
	}
	return db, nil
}

func GetTodos(db *sql.DB) ([]Todo, error) {
	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err = rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	if err = rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

func GetTodoByID(db *sql.DB, id int) (Todo, error) {
	var todo Todo
	err := db.QueryRow("SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1", id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return todo, err
	}
	return todo, nil
}

func CreateTodo(db *sql.DB, title string) (int64, error) {
	result, err := db.Exec("INSERT INTO todos (title, completed) VALUES ($1, $2)", title, false)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return id, nil
}

func UpdateTodo(db *sql.DB, id int, title string, completed bool) error {
	_, err := db.Exec("UPDATE todos SET title = $1, completed = $2 WHERE id = $3", title, completed, id)
	return err
}

func DeleteTodo(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM todos WHERE id = $1", id)
	return err
}

