package db

import (
	"database/sql"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func InitDB(dataSourceName string) (*sql.DB, error) {
	db, err := sql.Open("sqlite3", dataSourceName)
	if err != nil {
		return nil, err
	}
	return db, nil
}

func CreateTodo(db *sql.DB, todo *Todo) error {
	stmt, err := db.Prepare(`INSERT INTO todos (title, completed) VALUES (?, ?)`)
	if err != nil {
		return err
	}
	defer stmt.Close()

	result, err := stmt.Exec(todo.Title, todo.Completed)
	if err != nil {
		return err
	}

	id, err := result.LastInsertId()
	if err != nil {
		return err
	}

	todo.ID = int(id)
	currentTime := time.Now()
	todo.CreatedAt = currentTime
	todo.UpdatedAt = currentTime

	return nil
}

func GetTodo(db *sql.DB, id int) (*Todo, error) {
	var todo Todo
	err := db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?`, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func ListTodos(db *sql.DB) ([]*Todo, error) {
	rows, err := db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []*Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, &todo)
	}

	return todos, nil
}

func UpdateTodo(db *sql.DB, id int, todo *Todo) error {
	stmt, err := db.Prepare(`UPDATE todos SET title = ?, completed = ?, updated_at = ? WHERE id = ?`)
	if err != nil {
		return err
	}
	defer stmt.Close()

	currentTime := time.Now()
	_, err = stmt.Exec(todo.Title, todo.Completed, currentTime, id)
	if err != nil {
		return err
	}

	todo.UpdatedAt = currentTime

	return nil
}

func DeleteTodo(db *sql.DB, id int) error {
	stmt, err := db.Prepare(`DELETE FROM todos WHERE id = ?`)
	if err != nil {
		return err
	}
	defer stmt.Close()

	_, err = stmt.Exec(id)
	if err != nil {
		return err
	}

	return nil
}

