package db

import (
	"database/sql"
	"fmt"
	"log"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

var db *sql.DB

func init() {
	var err error
	port := "8080"
	if p := os.Getenv("PORT"); p != "" {
		port = p
	}
	connStr := fmt.Sprintf("host=localhost port=%s user=postgres dbname=tododb sslmode=disable", port)
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatalf("could not connect to database: %v", err)
	}
}

func GetTodos() ([]Todo, error) {
	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	return todos, nil
}

func GetTodoByID(id int) (*Todo, error) {
	var todo Todo
	err := db.QueryRow("SELECT id, title, completed, created_at, updated_at FROM todos WHERE id=$1", id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}

	return &todo, nil
}

func CreateTodo(todo Todo) error {
	result, err := db.Exec("INSERT INTO todos (title, completed) VALUES ($1, $2)", todo.Title, todo.Completed)
	if err != nil {
		return err
	}
	lastID, err := result.LastInsertId()
	if err != nil {
		return err
	}
	todo.ID = int(lastID)
	return nil
}

func UpdateTodo(todo Todo) error {
	result, err := db.Exec("UPDATE todos SET title=$1, completed=$2 WHERE id=$3", todo.Title, todo.Completed, todo.ID)
	if err != nil {
		return err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rowsAffected == 0 {
		return sql.ErrNoRows
	}

	return nil
}

func DeleteTodo(id int) error {
	result, err := db.Exec("DELETE FROM todos WHERE id=$1", id)
	if err != nil {
		return err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rowsAffected == 0 {
		return sql.ErrNoRows
	}

	return nil
}

