	r.Get("/{id}", getTodo(db))
	r.Put("/{id}", updateTodo(db))
	r.Delete("/{id}", deleteTodo(db))
	return r
}

func createTodo(db *db.SQLDB) func(w http.ResponseWriter, r *http.Request) {
	return func(w http.ResponseWriter, r *http.Request) {
		var todo db.Todo
		if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}
		id, err := db.CreateTodo(todo.Title, todo.Completed)
		if err != nil {
			http.Error(w, "Error creating todo", http.StatusInternalServerError)
			return
		}
		render.JSON(w, r, TodoResponse{ID: int(id), Title: todo.Title, Completed: todo.Completed})
	}
}

func listTodos(db *db.SQLDB) func(w http.ResponseWriter, r *http.Request) {
	return func(w http.ResponseWriter, r *http.Request) {
		todos, err := db.ListTodos()
		if err != nil {
			http.Error(w, "Error listing todos", http.StatusInternalServerError)
			return
		}
		var todoResponses []TodoResponse
		for _, todo := range todos {
			todoResponses = append(todoResponses, TodoResponse{ID: todo.ID, Title: todo.Title, Completed: todo.Completed})
		}
		render.JSON(w, r, todoResponses)
	}
}

