		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid ID", http.StatusBadRequest)
			return
		}
		todo, err := db.GetTodo(id)
		if err != nil {
			http.Error(w, "Error getting todo", http.StatusInternalServerError)
			return
		}
		if todo == nil {
			http.Error(w, "Todo not found", http.StatusNotFound)
			return
		}
		render.JSON(w, r, TodoResponse{ID: todo.ID, Title: todo.Title, Completed: todo.Completed})
	}
}

func updateTodo(db *db.SQLDB) func(w http.ResponseWriter, r *http.Request) {
	return func(w http.ResponseWriter, r *http.Request) {
		idStr := chi.URLParam(r, "id")
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid ID", http.StatusBadRequest)
