package db

import (
	"database/sql"
	"time"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID         int       `json:"id"`
	Title      string    `json:"title"`
	Completed  bool      `json:"completed"`
	CreatedAt  time.Time `json:"created_at"`
	UpdatedAt  time.Time `json:"updated_at"`
}

func ConnectDB(dataSourceName string) (*sql.DB, error) {
	return sql.Open("postgres", dataSourceName)
}

func (t *Todo) Create(db *sql.DB) error {
	query := `
		INSERT INTO todos (title, completed)
		VALUES ($1, $2)
		RETURNING id, created_at, updated_at
	`
	err := db.QueryRow(query, t.Title, t.Completed).Scan(&t.ID, &t.CreatedAt, &t.UpdatedAt)
	return err
}

func GetTodos(db *sql.DB) ([]Todo, error) {
	query := `
		SELECT id, title, completed, created_at, updated_at
		FROM todos
	`
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	return todos, nil
}

func GetTodoByID(db *sql.DB, id int) (*Todo, error) {
	query := `
		SELECT id, title, completed, created_at, updated_at
		FROM todos
		WHERE id = $1
	`
	var todo Todo
	err := db.QueryRow(query, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	return &todo, err
}

func (t *Todo) Update(db *sql.DB) error {
	query := `
		UPDATE todos
		SET title = $1, completed = $2, updated_at = CURRENT_TIMESTAMP
		WHERE id = $3
	`
	_, err := db.Exec(query, t.Title, t.Completed, t.ID)
	return err
}

func (t *Todo) Delete(db *sql.DB) error {
	query := `
		DELETE FROM todos
		WHERE id = $1
	`
	_, err := db.Exec(query, t.ID)
	return err
}

