	if err != nil {
		return nil, err
	}
	return db, nil
}

func CreateTodo(db *sql.DB, title string, completed bool) (int64, error) {
	result, err := db.Exec(`
		INSERT INTO todos (title, completed)
		VALUES ($1, $2)
	`, title, completed)
	if err != nil {
		return 0, err
	}
	return result.LastInsertId()
}

func GetTodo(db *sql.DB, id int) (*Todo, error) {
	var todo Todo
	err := db.QueryRow(`
		SELECT id, title, completed, created_at, updated_at
		FROM todos
		WHERE id = $1
	`, id).Scan(
		&todo.ID,
		&todo.Title,
		&todo.Completed,
		&todo.CreatedAt,
		&todo.UpdatedAt,
	)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func ListTodos(db *sql.DB) ([]Todo, error) {
	rows, err := db.Query(`
		SELECT id, title, completed, created_at, updated_at
		FROM todos
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(
			&todo.ID,
			&todo.Title,
			&todo.Completed,
			&todo.CreatedAt,
			&todo.UpdatedAt,
		)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	err = rows.Err()
	if err != nil {
		return nil, err
	}
	return todos, nil
}

func UpdateTodo(db *sql.DB, id int, title string, completed bool) error {
	_, err := db.Exec(`
		UPDATE todos
		SET title = $1, completed = $2
		WHERE id = $3
	`, title, completed, id)
	if err != nil {
		return err
	}
	return nil
}

func DeleteTodo(db *sql.DB, id int) error {
	_, err := db.Exec(`
		DELETE FROM todos
		WHERE id = $1
	`, id)
	if err != nil {
		return err
	}
	return nil
}

