package db

import (
	"database/sql"
	"log"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

var db *sql.DB

func InitDB(dataSourceName string) error {
	var err error
	db, err = sql.Open("postgres", dataSourceName)
	if err != nil {
		return err
	}
	return nil
}

func GetTodos() ([]Todo, error) {
	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err = rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	err = rows.Err()
	if err != nil {
		return nil, err
	}

	return todos, nil
}

func GetTodoByID(id int) (*Todo, error) {
	row := db.QueryRow("SELECT id, title, completed, created_at, updated_at FROM todos WHERE id=$1", id)
	var todo Todo
	err := row.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &todo, nil
}

func CreateTodo(title string) (*Todo, error) {
	var todo Todo
	err := db.QueryRow("INSERT INTO todos (title) VALUES ($1) RETURNING id, title, completed, created_at, updated_at", title).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func UpdateTodo(id int, title *string, completed *bool) (*Todo, error) {
	var todo Todo
	query := "UPDATE todos SET"
	params := []interface{}{id}
	i := 1

	if title != nil {
		query += fmt.Sprintf(" title=$%d", i)
		params = append(params, *title)
		i++
	}

	if completed != nil {
		if len(query) > len("UPDATE todos SET") {
			query += ","
		}
		query += fmt.Sprintf(" completed=$%d", i)
		params = append(params, *completed)
		i++
	}

	query += " WHERE id=$" + fmt.Sprintf("%d RETURNING id, title, completed, created_at, updated_at", i)
	err := db.QueryRow(query, params...).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func DeleteTodo(id int) error {
	_, err := db.Exec("DELETE FROM todos WHERE id=$1", id)
	return err
}

