package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/gorilla/mux"
	"yourapp/db"
)

func SetupRoutes(r *mux.Router, db *db.SQL) {
	r.HandleFunc("/todos", ListTodosHandler(db)).Methods("GET")
	r.HandleFunc("/todos/{id}", GetTodoHandler(db)).Methods("GET")
	r.HandleFunc("/todos", CreateTodoHandler(db)).Methods("POST")
	r.HandleFunc("/todos/{id}", UpdateTodoHandler(db)).Methods("PUT")
	r.HandleFunc("/todos/{id}", DeleteTodoHandler(db)).Methods("DELETE")
}

func ListTodosHandler(db *db.SQL) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		todos, err := db.ListTodos()
		if err != nil {
			http.Error(w, "Failed to list todos", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(todos)
	}
}

func GetTodoHandler(db *db.SQL) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		vars := mux.Vars(r)
		idStr := vars["id"]
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid todo ID", http.StatusBadRequest)
			return
		}

		todo, err := db.GetTodo(id)
		if err != nil {
			if err == sql.ErrNoRows {
				http.Error(w, "Todo not found", http.StatusNotFound)
				return
			}
			http.Error(w, "Failed to get todo", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(todo)
	}
}

func CreateTodoHandler(db *db.SQL) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var newTodo db.Todo
		err := json.NewDecoder(r.Body).Decode(&newTodo)
		if err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}

		todo, err := db.CreateTodo(newTodo.Title, newTodo.Completed)
		if err != nil {
			http.Error(w, "Failed to create todo", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(todo)
	}
}

func UpdateTodoHandler(db *db.SQL) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		vars := mux.Vars(r)
		idStr := vars["id"]
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid todo ID", http.StatusBadRequest)
			return
		}

		var updateData map[string]interface{}
		err = json.NewDecoder(r.Body).Decode(&updateData)
		if err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}

		var title string
		var completed bool
		var hasTitle, hasCompleted bool

		if val, ok := updateData["title"]; ok {
			title = val.(string)
			hasTitle = true
		}

		if val, ok := updateData["completed"]; ok {
			completed = val.(bool)
			hasCompleted = true
		}

		var todo *db.Todo
		if hasTitle && hasCompleted {
			todo, err = db.UpdateTodo(id, title, completed)
		} else if hasTitle {
			todo, err = db.UpdateTodo(id, title, nil)
		} else if hasCompleted {
			todo, err = db.UpdateTodo(id, nil, completed)
		}

		if err != nil {
			if err == sql.ErrNoRows {
				http.Error(w, "Todo not found", http.StatusNotFound)
				return
			}
			http.Error(w, "Failed to update todo", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(todo)
	}
}

func DeleteTodoHandler(db *db.SQL) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		vars := mux.Vars(r)
		idStr := vars["id"]
		id, err := strconv.Atoi(idStr)
		if err != nil {
			http.Error(w, "Invalid todo ID", http.StatusBadRequest)
			return
		}

		err = db.DeleteTodo(id)
		if err != nil {
			if err == sql.ErrNoRows {
				http.Error(w, "Todo not found", http.StatusNotFound)
				return
			}
			http.Error(w, "Failed to delete todo", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}

