package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

func ConnectDB() (*sql.DB, error) {
	connStr := "user=postgres dbname=todos sslmode=disable"
	db, err := sql.Open("postgres", connStr)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to database: %v", err)
	}
	return db, nil
}

func CreateTodo(db *sql.DB, title string) (int, error) {
	var id int
	err := db.QueryRow(`INSERT INTO todos (title, completed) VALUES ($1, false) RETURNING id`, title).Scan(&id)
	if err != nil {
		return 0, fmt.Errorf("failed to create todo: %v", err)
	}
	return id, nil
}

func GetTodo(db *sql.DB, id int) (*Todo, error) {
	var todo Todo
	err := db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1`, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("todo not found")
	}
	if err != nil {
		return nil, fmt.Errorf("failed to get todo: %v", err)
	}
	return &todo, nil
}

func ListTodos(db *sql.DB) ([]Todo, error) {
	rows, err := db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos`)
	if err != nil {
		return nil, fmt.Errorf("failed to list todos: %v", err)
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %v", err)
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("failed to iterate rows: %v", err)
	}

	return todos, nil
}

func UpdateTodo(db *sql.DB, id int, title string, completed bool) error {
	result, err := db.Exec(`UPDATE todos SET title = $1, completed = $2 WHERE id = $3`, title, completed, id)
	if err != nil {
		return fmt.Errorf("failed to update todo: %v", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get rows affected: %v", err)
	}
	if rowsAffected == 0 {
		return fmt.Errorf("todo not found")
	}
	return nil
}

func DeleteTodo(db *sql.DB, id int) error {
	result, err := db.Exec(`DELETE FROM todos WHERE id = $1`, id)
	if err != nil {
		return fmt.Errorf("failed to delete todo: %v", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get rows affected: %v", err)
	}
	if rowsAffected == 0 {
		return fmt.Errorf("todo not found")
	}
	return nil
}

