	var todo Todo
	err := row.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}

	return &todo, nil
}

func CreateTodo(todo Todo) (int64, error) {
	result, err := db.Exec(`INSERT INTO todos (title, completed) VALUES ($1, $2) RETURNING id`, todo.Title, todo.Completed)
	if err != nil {
		return 0, err
	}

	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}

	return id, nil
}

