	"time"

	_ "github.com/mattn/go-sqlite3"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func ConnectDB(dataSourceName string) (*sql.DB, error) {
	db, err := sql.Open("sqlite3", dataSourceName)
	if err != nil {
		return nil, err
	}
	return db, nil
}

func (db *sql.DB) CreateTodo(todo Todo) error {
	query := `
		INSERT INTO todos (title, completed)
		VALUES (?, ?)
	`
	_, err := db.Exec(query, todo.Title, todo.Completed)
	if err != nil {
		return err
	}
	return nil
}

func (db *sql.DB) GetTodos() ([]Todo, error) {
	query := `
		SELECT id, title, completed, created_at, updated_at
		FROM todos
	`
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	return todos, nil
}

func (db *sql.DB) GetTodoByID(id int) (*Todo, error) {
	query := `
		SELECT id, title, completed, created_at, updated_at
		FROM todos
		WHERE id = ?
	`
	var todo Todo
	err := db.QueryRow(query, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &todo, nil
}

func (db *sql.DB) UpdateTodoByID(id int, todo Todo) error {
	query := `
		UPDATE todos
		SET title = ?, completed = ?
		WHERE id = ?
	`
	_, err := db.Exec(query, todo.Title, todo.Completed, id)
	if err != nil {
		return err
	}
	return nil
}

func (db *sql.DB) DeleteTodoByID(id int) error {
	query := `
		DELETE FROM todos
		WHERE id = ?
	`
	_, err := db.Exec(query, id)
	if err != nil {
		return err
	}
	return nil
}

