func TestCreateTodo(t *testing.T) {
	db, cleanup := setupTestDB(t)
	defer cleanup()

	todo := Todo{
		Title:     "Test Todo",
		Completed: false,
	}

	err := db.CreateTodo(todo)
	assert.NoError(t, err)

	var createdTodo Todo
	query := `
		SELECT id, title, completed, created_at, updated_at
		FROM todos
		WHERE title = ?
	`
	row := db.QueryRow(query, todo.Title)
	err = row.Scan(&createdTodo.ID, &createdTodo.Title, &createdTodo.Completed, &createdTodo.CreatedAt, &createdTodo.UpdatedAt)
	assert.NoError(t, err)

	assert.Equal(t, todo.Title, createdTodo.Title)
	assert.Equal(t, todo.Completed, createdTodo.Completed)
}

func TestGetTodos(t *testing.T) {
	db, cleanup := setupTestDB(t)
	defer cleanup()

	todo1 := Todo{
		Title:     "Test Todo 1",
		Completed: false,
	}
	err := db.CreateTodo(todo1)
	assert.NoError(t, err)

	todo2 := Todo{
		Title:     "Test Todo 2",
		Completed: true,
	}
	err = db.CreateTodo(todo2)
	assert.NoError(t, err)

	todos, err := db.GetTodos()
	assert.NoError(t, err)
	assert.Len(t, todos, 2)

	for _, todo := range todos {
		if todo.Title == "Test Todo 1" {
			assert.False(t, todo.Completed)
		} else if todo.Title == "Test Todo 2" {
			assert.True(t, todo.Completed)
		}
	}
}

func TestGetTodoByID(t *testing.T) {
	db, cleanup := setupTestDB(t)
	defer cleanup()

	todo := Todo{
		Title:     "Test Todo",
		Completed: false,
	}
	err := db.CreateTodo(todo)
	assert.NoError(t, err)

	fetchedTodo, err := db.GetTodoByID(todo.ID)
	assert.NoError(t, err)
	assert.NotNil(t, fetchedTodo)
	assert.Equal(t, todo.Title, fetchedTodo.Title)
	assert.Equal(t, todo.Completed, fetchedTodo.Completed)
}

func TestUpdateTodoByID(t *testing.T) {
	db, cleanup := setupTestDB(t)
	defer cleanup()

	todo := Todo{
		Title:     "Test Todo",
		Completed: false,
	}
	err := db.CreateTodo(todo)
	assert.NoError(t, err)

	updatedTodo := Todo{
		ID:        todo.ID,
		Title:     "Updated Todo Title",
		Completed: true,
	}
	err = db.UpdateTodoByID(todo.ID, updatedTodo)
	assert.NoError(t, err)

	fetchedTodo, err := db.GetTodoByID(todo.ID)
	assert.NoError(t, err)
	assert.NotNil(t, fetchedTodo)
	assert.Equal(t, updatedTodo.Title, fetchedTodo.Title)
	assert.Equal(t, updatedTodo.Completed, fetchedTodo.Completed)
}

func TestDeleteTodoByID(t *testing.T) {
	db, cleanup := setupTestDB(t)
	defer cleanup()

	todo := Todo{
		Title:     "Test Todo",
		Completed: false,
	}
	err := db.CreateTodo(todo)
	assert.NoError(t, err)

	err = db.DeleteTodoByID(todo.ID)
	assert.NoError(t, err)

	fetchedTodo, err := db.GetTodoByID(todo.ID)
	assert.NoError(t, err)
	assert.Nil(t, fetchedTodo)
}

func setupTestDB(t *testing.T) (*sql.DB, func()) {
	db, err := ConnectDB(":memory:")
	if err != nil {
		t.Fatalf("Failed to connect to database: %v", err)
	}

	initSQL := `
		CREATE TABLE todos (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			title TEXT NOT NULL,
			completed BOOLEAN NOT NULL DEFAULT FALSE,
			created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
			updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
		);
	`
	_, err = db.Exec(initSQL)
	if err != nil {
		t.Fatalf("Failed to initialize database: %v", err)
	}

	return db, func() {
		db.Close()
	}
}

