	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func (h *TodoHandler) UpdateTodoByID(w http.ResponseWriter, r *http.Request) {
	id := getIDFromRequest(r)
	var todo db.Todo
	err := json.NewDecoder(r.Body).Decode(&todo)
	if err != nil {
		http.Error(w, "Bad Request", http.StatusBadRequest)
		return
	}

	todo.ID = id
	err = h.DB.UpdateTodoByID(id, todo)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func (h *TodoHandler) DeleteTodoByID(w http.ResponseWriter, r *http.Request) {
	id := getIDFromRequest(r)
	err := h.DB.DeleteTodoByID(id)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func getIDFromRequest(r *http.Request) int {
	urlParams := r.URL.Query()
	idStr := urlParams.Get(":id")
	id, _ := strconv.Atoi(idStr)
	return id
}

