package db

import (
	"database/sql"
	"fmt"

	_ "github.com/mattn/go-sqlite3"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

var db *sql.DB

func InitDB(dataSourceName string) error {
	var err error
	db, err = sql.Open("sqlite3", dataSourceName)
	if err != nil {
		return fmt.Errorf("failed to open database: %w", err)
	}
	return nil
}

func CreateTodo(todo Todo) (int64, error) {
	result, err := db.Exec(`INSERT INTO todos (title, completed) VALUES (?, ?)`, todo.Title, todo.Completed)
	if err != nil {
		return 0, fmt.Errorf("failed to create todo: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("failed to get last insert id: %w", err)
	}
	return id, nil
}

func GetTodoByID(id int) (Todo, error) {
	var todo Todo
	err := db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?`, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return Todo{}, fmt.Errorf("todo not found: %w", err)
		}
		return Todo{}, fmt.Errorf("failed to get todo: %w", err)
	}
	return todo, nil
}

func ListTodos() ([]Todo, error) {
	rows, err := db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos`)
	if err != nil {
		return nil, fmt.Errorf("failed to list todos: %w", err)
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("rows error: %w", err)
	}

	return todos, nil
}

func UpdateTodo(id int, updates map[string]interface{}) (int64, error) {
	query := "UPDATE todos SET "
	params := []interface{}{id}
	setClauses := make([]string, 0)

	if title, ok := updates["title"].(string); ok {
		setClauses = append(setClauses, "title = ?")
		params = append(params, title)
	}

	if completed, ok := updates["completed"].(bool); ok {
		setClauses = append(setClauses, "completed = ?")
		params = append(params, completed)
	}

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no valid fields to update")
	}

	query += strings.Join(setClauses, ", ") + " WHERE id = ?"
	result, err := db.Exec(query, params...)
	if err != nil {
		return 0, fmt.Errorf("failed to update todo: %w", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("failed to get rows affected: %w", err)
	}
	return rowsAffected, nil
}

func DeleteTodo(id int) (int64, error) {
	result, err := db.Exec(`DELETE FROM todos WHERE id = ?`, id)
	if err != nil {
		return 0, fmt.Errorf("failed to delete todo: %w", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("failed to get rows affected: %w", err)
	}
	return rowsAffected, nil
}

func CloseDB() error {
	err := db.Close()
	if err != nil {
		return fmt.Errorf("failed to close database: %w", err)
	}
	return nil
}

