package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

func NewDB(dataSourceName string) (*sql.DB, error) {
	db, err := sql.Open("postgres", dataSourceName)
	if err != nil {
		return nil, fmt.Errorf("failed to open database: %w", err)
	}
	return db, nil
}

func (db *sql.DB) ListTodos() ([]Todo, error) {
	rows, err := db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos`)
	if err != nil {
		return nil, fmt.Errorf("failed to list todos: %w", err)
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}
		todos = append(todos, todo)
	}
	return todos, nil
}

func (db *sql.DB) GetTodo(id int) (*Todo, error) {
	var todo Todo
	err := db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id=$1`, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("todo not found: %w", err)
		}
		return nil, fmt.Errorf("failed to get todo: %w", err)
	}
	return &todo, nil
}

func (db *sql.DB) CreateTodo(todo Todo) (*Todo, error) {
	var id int
	err := db.QueryRow(`INSERT INTO todos(title, completed) VALUES($1, $2) RETURNING id`, todo.Title, todo.Completed).Scan(&id)
	if err != nil {
		return nil, fmt.Errorf("failed to create todo: %w", err)
	}
	todo.ID = id
	return &todo, nil
}

func (db *sql.DB) UpdateTodo(id int, update Todo) (*Todo, error) {
	var todo Todo
	err := db.QueryRow(`UPDATE todos SET title=$1, completed=$2 WHERE id=$3 RETURNING id, title, completed, created_at, updated_at`, update.Title, update.Completed, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("todo not found: %w", err)
		}
		return nil, fmt.Errorf("failed to update todo: %w", err)
	}
	return &todo, nil
}

func (db *sql.DB) DeleteTodo(id int) error {
	if _, err := db.Exec(`DELETE FROM todos WHERE id=$1`, id); err != nil {
		return fmt.Errorf("failed to delete todo: %w", err)
	}
	return nil
}

