package main

import (
	"log"
	"net/http"
	"os"

	"github.com/yourusername/todo-app/db"
	"github.com/yourusername/todo-app/handlers"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	dataSourceName := "postgres://user:password@localhost/todo_db?sslmode=disable"
	database, err := db.NewDB(dataSourceName)
	if err != nil {
		log.Fatalf("failed to connect to database: %v", err)
	}
	defer database.Close()

	todosHandler := handlers.TodosHandler{DB: database}

	mux := http.NewServeMux()
	mux.HandleFunc("/todos", todosHandler.ListTodos)
	mux.HandleFunc("/todos/", todosHandler.GetTodo)
	mux.HandleFunc("/todos", todosHandler.CreateTodo)
	mux.HandleFunc("/todos/", todosHandler.UpdateTodo)
	mux.HandleFunc("/todos/", todosHandler.DeleteTodo)

	log.Printf("starting server on port %s", port)
	if err := http.ListenAndServe(":"+port, mux); err != nil {
		log.Fatalf("failed to start server: %v", err)
	}
}

