	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos)
}

func GetTodo(w http.ResponseWriter, r *http.Request, ps httprouter.Params) {
	db := db.Connect()
	defer db.Close()

	id, err := strconv.Atoi(ps.ByName("id"))
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	todo, err := db.GetTodo(db, id)
	if err != nil {
		http.Error(w, "Failed to get todo", http.StatusInternalServerError)
		return
	}
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func CreateTodo(w http.ResponseWriter, r *http.Request, _ httprouter.Params) {
	var todo db.Todo
	err := json.NewDecoder(r.Body).Decode(&todo)
	if err != nil || (todo.Title == "" && !todo.Completed) {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	db := db.Connect()
	defer db.Close()

	id, err := db.CreateTodo(db, todo)
	if err != nil {
		http.Error(w, "Failed to create todo", http.StatusInternalServerError)
		return
	}

	todo.ID = id

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(todo)
}

func UpdateTodo(w http.ResponseWriter, r *http.Request, ps httprouter.Params) {
	id, err := strconv.Atoi(ps.ByName("id"))
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var update db.Todo
	err = json.NewDecoder(r.Body).Decode(&update)
	if err != nil || (update.Title == "" && !update.Completed) {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	db := db.Connect()
	defer db.Close()

	todo, err := db.GetTodo(db, id)
	if err != nil {
		http.Error(w, "Failed to get todo", http.StatusInternalServerError)
		return
	}
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	todo.Title = update.Title
	todo.Completed = update.Completed

	err = db.UpdateTodo(db, id, *todo)
	if err != nil {
		http.Error(w, "Failed to update todo", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func DeleteTodo(w http.ResponseWriter, r *http.Request, ps httprouter.Params) {
	id, err := strconv.Atoi(ps.ByName("id"))
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	db := db.Connect()
	defer db.Close()

	todo, err := db.GetTodo(db, id)
	if err != nil {
		http.Error(w, "Failed to get todo", http.StatusInternalServerError)
		return
	}
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	err = db.DeleteTodo(db, id)
	if err != nil {
		http.Error(w, "Failed to delete todo", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

