package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

type DB struct {
	*sql.DB
}

func NewDB(dataSourceName string) (*DB, error) {
	db, err := sql.Open("postgres", dataSourceName)
	if err != nil {
		return nil, err
	}
	return &DB{db}, nil
}

func (d *DB) ListTodos() ([]Todo, error) {
	rows, err := d.Query(`SELECT id, title, completed, created_at, updated_at FROM todos`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

func (d *DB) GetTodo(id int) (*Todo, error) {
	var todo Todo
	err := d.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1`, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("not found: %w", err)
	}
	if err != nil {
		return nil, err
	}

	return &todo, nil
}

func (d *DB) CreateTodo(title string) (*Todo, error) {
	var todo Todo
	err := d.QueryRow(`INSERT INTO todos (title) VALUES ($1) RETURNING id, title, completed, created_at, updated_at`, title).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}

	return &todo, nil
}

func (d *DB) UpdateTodo(id int, todo Todo) (*Todo, error) {
	var updatedTodo Todo
	err := d.QueryRow(`UPDATE todos SET title = $1, completed = $2 WHERE id = $3 RETURNING id, title, completed, created_at, updated_at`, todo.Title, todo.Completed, id).Scan(&updatedTodo.ID, &updatedTodo.Title, &updatedTodo.Completed, &updatedTodo.CreatedAt, &updatedTodo.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("not found: %w", err)
	}
	if err != nil {
		return nil, err
	}

	return &updatedTodo, nil
}

func (d *DB) DeleteTodo(id int) error {
	result, err := d.Exec(`DELETE FROM todos WHERE id = $1`, id)
	if err != nil {
		return err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rowsAffected == 0 {
		return fmt.Errorf("not found")
	}

	return nil
}

