package handlers

import (
	"encoding/json"
	"fmt"
	"net/http"

	"github.com/yourusername/todo-app/db"
)

type TodosHandler struct {
	DB *db.DB
}

func NewTodosHandler(db *db.DB) *TodosHandler {
	return &TodosHandler{DB: db}
}

func (h *TodosHandler) List(w http.ResponseWriter, r *http.Request) {
	todos, err := h.DB.ListTodos()
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos)
}

func (h *TodosHandler) Get(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Error(w, "Bad Request: missing id", http.StatusBadRequest)
		return
	}
	id, err := fmt.Atoi(idStr)
	if err != nil {
		http.Error(w, "Bad Request: invalid id", http.StatusBadRequest)
		return
	}

	todo, err := h.DB.GetTodo(id)
	if err != nil {
		http.Error(w, "Not Found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func (h *TodosHandler) Create(w http.ResponseWriter, r *http.Request) {
	var todo db.Todo
	err := json.NewDecoder(r.Body).Decode(&todo)
	if err != nil {
		http.Error(w, "Bad Request", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	newTodo, err := h.DB.CreateTodo(todo.Title)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(newTodo)
}

func (h *TodosHandler) Update(w http.ResponseWriter, r *http.Request) {
	var todo db.Todo
	err := json.NewDecoder(r.Body).Decode(&todo)
	if err != nil {
		http.Error(w, "Bad Request", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Error(w, "Bad Request: missing id", http.StatusBadRequest)
		return
	}
	id, err := fmt.Atoi(idStr)
	if err != nil {
		http.Error(w, "Bad Request: invalid id", http.StatusBadRequest)
		return
	}

	todo.ID = id
	updatedTodo, err := h.DB.UpdateTodo(todo.ID, todo)
	if err != nil {
		http.Error(w, "Not Found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(updatedTodo)
}

func (h *TodosHandler) Delete(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Error(w, "Bad Request: missing id", http.StatusBadRequest)
		return
	}
	id, err := fmt.Atoi(idStr)
	if err != nil {
		http.Error(w, "Bad Request: invalid id", http.StatusBadRequest)
		return
	}

	err = h.DB.DeleteTodo(id)
	if err != nil {
		http.Error(w, "Not Found", http.StatusNotFound)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

