package db

import (
	"database/sql"
	"fmt"

	_ "github.com/mattn/go-sqlite3"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

func OpenDB(dataSourceName string) (*sql.DB, error) {
	return sql.Open("sqlite3", dataSourceName)
}

func CreateTables(db *sql.DB) error {
	query := `
	CREATE TABLE IF NOT EXISTS todos (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		title TEXT NOT NULL,
		completed BOOLEAN NOT NULL DEFAULT FALSE,
		created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
		updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
	);
	`
	_, err := db.Exec(query)
	return err
}

func GetTodos(db *sql.DB) ([]Todo, error) {
	query := "SELECT id, title, completed, created_at, updated_at FROM todos"
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	return todos, nil
}

func GetTodoByID(db *sql.DB, id int) (*Todo, error) {
	query := "SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?"
	row := db.QueryRow(query, id)

	var todo Todo
	if err := row.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("todo not found: %w", err)
		}
		return nil, err
	}

	return &todo, nil
}

func CreateTodo(db *sql.DB, title string, completed bool) (*Todo, error) {
	query := "INSERT INTO todos (title, completed) VALUES (?, ?)"
	result, err := db.Exec(query, title, completed)
	if err != nil {
		return nil, err
	}

	id, err := result.LastInsertId()
	if err != nil {
		return nil, err
	}

	todo := &Todo{
		ID:        int(id),
		Title:     title,
		Completed: completed,
	}
	return todo, nil
}

func UpdateTodo(db *sql.DB, id int, title string, completed bool) (*Todo, error) {
	query := "UPDATE todos SET title = ?, completed = ? WHERE id = ?"
	result, err := db.Exec(query, title, completed, id)
	if err != nil {
		return nil, err
	}

	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return nil, err
	}
	if rowsAffected == 0 {
		return nil, fmt.Errorf("todo not found: %w", sql.ErrNoRows)
	}

	todo := &Todo{
		ID:        id,
		Title:     title,
		Completed: completed,
	}
	return todo, nil
}

func DeleteTodo(db *sql.DB, id int) error {
	query := "DELETE FROM todos WHERE id = ?"
	result, err := db.Exec(query, id)
	if err != nil {
		return err
	}

	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rowsAffected == 0 {
		return fmt.Errorf("todo not found: %w", sql.ErrNoRows)
	}

	return nil
}

