package db

import (
	"database/sql"
	"fmt"

	_ "github.com/mattn/go-sqlite3"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

func OpenDB() (*sql.DB, error) {
	return sql.Open("sqlite3", "./todo.db")
}

func CreateTables(db *sql.DB) error {
	query := `
	CREATE TABLE IF NOT EXISTS todos (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		title TEXT NOT NULL,
		completed BOOLEAN NOT NULL DEFAULT FALSE,
		created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
		updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
	);
	`
	_, err := db.Exec(query)
	return err
}

func GetTodos(db *sql.DB) ([]Todo, error) {
	query := "SELECT id, title, completed, created_at, updated_at FROM todos"
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	return todos, nil
}

func GetTodoByID(db *sql.DB, id int) (*Todo, error) {
	query := "SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?"
	var todo Todo
	err := db.QueryRow(query, id).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("not found: %w", err)
		}
		return nil, err
	}

	return &todo, nil
}

func CreateTodo(db *sql.DB, todo Todo) error {
	query := "INSERT INTO todos (title, completed) VALUES (?, ?)"
	_, err := db.Exec(query, todo.Title, todo.Completed)
	if err != nil {
		return err
	}

	return nil
}

func UpdateTodoByID(db *sql.DB, id int, update Todo) error {
	query := "UPDATE todos SET title = ?, completed = ? WHERE id = ?"
	_, err := db.Exec(query, update.Title, update.Completed, id)
	if err != nil {
		return err
	}

	return nil
}

func DeleteTodoByID(db *sql.DB, id int) error {
	query := "DELETE FROM todos WHERE id = ?"
	_, err := db.Exec(query, id)
	if err != nil {
		return err
	}

	return nil
}

