package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

func ConnectDB(dataSourceName string) (*sql.DB, error) {
	db, err := sql.Open("postgres", dataSourceName)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to database: %w", err)
	}
	err = db.Ping()
	if err != nil {
		return nil, fmt.Errorf("failed to ping database: %w", err)
	}
	return db, nil
}

func CreateTodo(db *sql.DB, title string) (*Todo, error) {
	var id int
	row := db.QueryRow(`INSERT INTO todos (title) VALUES ($1) RETURNING id`, title)
	err := row.Scan(&id)
	if err != nil {
		return nil, fmt.Errorf("failed to create todo: %w", err)
	}
	return &Todo{ID: id, Title: title, Completed: false}, nil
}

func GetTodo(db *sql.DB, id int) (*Todo, error) {
	var todo Todo
	err := db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1`, id).Scan(
		&todo.ID,
		&todo.Title,
		&todo.Completed,
		&todo.CreatedAt,
		&todo.UpdatedAt,
	)
	if err != nil {
		return nil, fmt.Errorf("failed to get todo: %w", err)
	}
	return &todo, nil
}

func ListTodos(db *sql.DB) ([]*Todo, error) {
	rows, err := db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos`)
	if err != nil {
		return nil, fmt.Errorf("failed to list todos: %w", err)
	}
	defer rows.Close()

	var todos []*Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(
			&todo.ID,
			&todo.Title,
			&todo.Completed,
			&todo.CreatedAt,
			&todo.UpdatedAt,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}
		todos = append(todos, &todo)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("failed to iterate rows: %w", err)
	}

	return todos, nil
}

func UpdateTodo(db *sql.DB, id int, title string, completed bool) (*Todo, error) {
	var todo Todo
	err := db.QueryRow(`UPDATE todos SET title = $2, completed = $3 WHERE id = $1 RETURNING id, title, completed, created_at, updated_at`, id, title, completed).Scan(
		&todo.ID,
		&todo.Title,
		&todo.Completed,
		&todo.CreatedAt,
		&todo.UpdatedAt,
	)
	if err != nil {
		return nil, fmt.Errorf("failed to update todo: %w", err)
	}
	return &todo, nil
}

func DeleteTodo(db *sql.DB, id int) error {
	_, err := db.Exec(`DELETE FROM todos WHERE id = $1`, id)
	if err != nil {
		return fmt.Errorf("failed to delete todo: %w", err)
	}
	return nil
}

