	id := getIDFromRequest(r)
	todo, err := db.GetTodo(db.DB, id)
	if err != nil {
		http.Error(w, "Not Found", http.StatusNotFound)
		return
	}

	json.NewEncoder(w).Encode(todo)
}

func ListTodosHandler(w http.ResponseWriter, r *http.Request) {
	todos, err := db.ListTodos(db.DB)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	json.NewEncoder(w).Encode(todos)
}

func UpdateTodoHandler(w http.ResponseWriter, r *http.Request) {
	id := getIDFromRequest(r)
	var todo db.Todo
	err := json.NewDecoder(r.Body).Decode(&todo)
	if err != nil || (todo.Title == "" && todo.Completed == false) {
		http.Error(w, "Bad Request", http.StatusBadRequest)
		return
	}

	todo, err = db.UpdateTodo(db.DB, id, todo.Title, todo.Completed)
	if err != nil {
		http.Error(w, "Not Found", http.StatusNotFound)
		return
	}

	json.NewEncoder(w).Encode(todo)
}

func DeleteTodoHandler(w http.ResponseWriter, r *http.Request) {
	id := getIDFromRequest(r)
	err := db.DeleteTodo(db.DB, id)
	if err != nil {
		http.Error(w, "Not Found", http.StatusNotFound)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

func getIDFromRequest(r *http.Request) int {
	vars := r.URL.Query()
	idStr := vars.Get("id")
	id, _ := strconv.Atoi(idStr)
	return id
}

