package db

import (
	"database/sql"
	"log"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

var DB *sql.DB

func InitDB(dataSourceName string) error {
	var err error
	DB, err = sql.Open("postgres", dataSourceName)
	if err != nil {
		return err
	}
	err = DB.Ping()
	if err != nil {
		return err
	}
	log.Println("Database connection established")
	return nil
}

func GetTodos() ([]Todo, error) {
	rows, err := DB.Query("SELECT id, title, completed, created_at, updated_at FROM todos ORDER BY id")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}
	if err = rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

func GetTodoByID(id int) (*Todo, error) {
	row := DB.QueryRow("SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1", id)
	var todo Todo
	err := row.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func CreateTodo(todo *Todo) error {
	err := DB.QueryRow(
		"INSERT INTO todos (title, completed) VALUES ($1, $2) RETURNING id, title, completed, created_at, updated_at",
		todo.Title, todo.Completed,
	).Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt)
	return err
}

func UpdateTodo(id int, updates map[string]interface{}) error {
	setClause := ""
	args := []interface{}{id}
	for key, value := range updates {
		setClause += key + " = $" + string(len(args)+1) + ", "
		args = append(args, value)
	}
	setClause = setClause[:len(setClause)-2]

	query := "UPDATE todos SET " + setClause + " WHERE id = $" + string(len(args)+1)
	_, err := DB.Exec(query, args...)
	return err
}

func DeleteTodo(id int) error {
	_, err := DB.Exec("DELETE FROM todos WHERE id = $1", id)
	return err
}

