package db

import (
	"database/sql"
	"time"

	"github.com/jmoiron/sqlx"
)

type Todo struct {
	ID        int       `db:"id"`
	Title     string    `db:"title"`
	Completed bool      `db:"completed"`
	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

func GetTodos(db *sqlx.DB) ([]Todo, error) {
	var todos []Todo
	err := db.Select(&todos, "SELECT id, title, completed, created_at, updated_at FROM todos")
	return todos, err
}

func GetTodoByID(db *sqlx.DB, id int) (Todo, error) {
	var todo Todo
	err := db.Get(&todo, "SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1", id)
	return todo, err
}

func CreateTodo(db *sqlx.DB, title string) (*Todo, error) {
	todo := &Todo{
		Title:     title,
		Completed: false,
	}
	err := db.Get(todo, "INSERT INTO todos (title, completed) VALUES ($1, $2) RETURNING id, title, completed, created_at, updated_at", todo.Title, todo.Completed)
	return todo, err
}

func UpdateTodo(db *sqlx.DB, id int, title *string, completed *bool) (*Todo, error) {
	var todo Todo
	query := "UPDATE todos SET"
	args := []interface{}{id}
	if title != nil {
		query += " title = $2,"
		args = append(args, *title)
	}
	if completed != nil {
		query += " completed = $3,"
		args = append(args, *completed)
	}
	if len(args) == 2 {
		return nil, sql.ErrNoRows
	}
	query = query[:len(query)-1] + " WHERE id = $1 RETURNING id, title, completed, created_at, updated_at"
	err := db.Get(&todo, query, args...)
	return &todo, err
}

func DeleteTodo(db *sqlx.DB, id int) error {
	_, err := db.Exec("DELETE FROM todos WHERE id = $1", id)
	return err
}

