	}
	defer db.Close()

	todos, err := GetTodos(db)
	if err != nil {
		t.Fatalf("Failed to get todos: %v", err)
	}

	expectedCount := 0
	rows, err := db.Query("SELECT COUNT(*) FROM todos")
	if err != nil {
		t.Fatalf("Failed to query count: %v", err)
	}
	defer rows.Close()

	for rows.Next() {
		err = rows.Scan(&expectedCount)
		if err != nil {
