package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/gorilla/mux"
	"github.com/jmoiron/sqlx"
	_ "github.com/lib/pq"

	dbpkg "github.com/yourusername/todo-app/db"
)

type TodosHandler struct {
	DB *sqlx.DB
}

func (h *TodosHandler) List(w http.ResponseWriter, r *http.Request) {
	todos, err := dbpkg.GetTodos(h.DB)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(todos)
}

func (h *TodosHandler) GetByID(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	idStr := vars["id"]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	todo, err := dbpkg.GetTodoByID(h.DB, id)
	if err != nil {
		http.Error(w, err.Error(), http.StatusNotFound)
		return
	}
	json.NewEncoder(w).Encode(todo)
}

func (h *TodosHandler) Create(w http.ResponseWriter, r *http.Request) {
	var todo dbpkg.Todo
	err := json.NewDecoder(r.Body).Decode(&todo)
	if err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	newTodo, err := dbpkg.CreateTodo(h.DB, todo.Title)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(newTodo)
}

func (h *TodosHandler) UpdateByID(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	idStr := vars["id"]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var update dbpkg.Todo
	err = json.NewDecoder(r.Body).Decode(&update)
	if err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	todo, err := dbpkg.UpdateTodo(h.DB, id, &update.Title, &update.Completed)
	if err != nil {
		http.Error(w, err.Error(), http.StatusNotFound)
		return
	}
	json.NewEncoder(w).Encode(todo)
}

func (h *TodosHandler) DeleteByID(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	idStr := vars["id"]
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	err = dbpkg.DeleteTodo(h.DB, id)
	if err != nil {
		http.Error(w, err.Error(), http.StatusNotFound)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func NewTodosHandler(db *sqlx.DB) *mux.Router {
	r := mux.NewRouter()
	h := &TodosHandler{DB: db}
	r.HandleFunc("/todos", h.List).Methods("GET")
	r.HandleFunc("/todos/{id}", h.GetByID).Methods("GET")
	r.HandleFunc("/todos", h.Create).Methods("POST")
	r.HandleFunc("/todos/{id}", h.UpdateByID).Methods("PUT")
	r.HandleFunc("/todos/{id}", h.DeleteByID).Methods("DELETE")
	return r
}

